import express from 'express';
import { randomBytes, randomUUID, timingSafeEqual } from 'crypto';
import { closeListener, listenLocally } from '../../library/http';
import type { ProfileRuntime } from '../../types/design-profile';
import type { ProfileAgent } from './ProfileAgent';
import { prepareModelRequest, reportedProfileUsage } from './modelContract';

interface ModelBinding {
  runtime: ProfileRuntime;
  signal?: AbortSignal;
  calls: number;
  maxModelCalls: number;
  refusedCalls: number;
}
export interface EngineBinding {
  maxModelCalls?: number;
  queueTimeoutMs?: number;
}
const MAX_MODEL_CALLS = 8;

export class ModelCallRefused extends Error {
  constructor() {
    super(
      'The search engine attempted a model call that this operation forbids',
    );
  }
}

export class EngineBusy extends Error {
  constructor() {
    super('The search engine is busy with other profile work');
  }
}

export class MemoryModelService {
  readonly token = randomBytes(32).toString('hex');
  private listener?: Awaited<ReturnType<typeof listenLocally>>;
  private binding?: ModelBinding;
  private tail: Promise<unknown> = Promise.resolve();
  constructor(private readonly agent: ProfileAgent) {}

  async start(): Promise<string> {
    const app = express();
    app.use((req, res, next) => {
      const actual = Buffer.from(req.header('x-api-key') ?? '');
      const expected = Buffer.from(this.token);
      if (
        actual.length !== expected.length ||
        !timingSafeEqual(actual, expected)
      ) {
        res.sendStatus(401);
        return;
      }
      next();
    });
    app.use(express.json({ limit: '256kb' }));
    app.post('/v1/messages', async (req, res) => {
      const binding = this.binding;
      if (!binding || ++binding.calls > binding.maxModelCalls) {
        if (binding) binding.refusedCalls += 1;
        res.status(503).json({
          error: {
            type: 'overloaded_error',
            message: 'No eligible profile task is bound to this operation',
          },
        });
        return;
      }
      try {
        const request = prepareModelRequest(req.body);
        const result = await this.agent.run({
          ...request,
          runtime: binding.runtime,
          signal: binding.signal,
        });
        const usage = reportedProfileUsage(result.usage);
        res.json({
          id: `msg_${randomUUID()}`,
          type: 'message',
          role: 'assistant',
          model: req.body.model,
          content: [{ type: 'text', text: JSON.stringify(result.value) }],
          stop_reason: 'end_turn',
          stop_sequence: null,
          usage: {
            input_tokens: usage.inputTokens ?? 0,
            output_tokens: usage.outputTokens ?? 0,
          },
        });
      } catch {
        res.status(502).json({
          error: {
            type: 'api_error',
            message:
              'The selected agent could not produce a valid profile result',
          },
        });
      }
    });
    this.listener = await listenLocally(app);
    return `${this.listener.url}/v1`;
  }

  withRuntime<T>(
    runtime: ProfileRuntime,
    operation: () => Promise<T>,
    signal?: AbortSignal,
    { maxModelCalls, queueTimeoutMs }: EngineBinding = {},
  ): Promise<T> {
    let isStarted = false;
    let isAbandoned = false;
    const run = this.tail
      .catch(() => undefined)
      .then(async () => {
        if (isAbandoned) throw new EngineBusy();
        isStarted = true;
        signal?.throwIfAborted();
        const binding: ModelBinding = {
          runtime,
          signal,
          calls: 0,
          maxModelCalls: maxModelCalls ?? MAX_MODEL_CALLS,
          refusedCalls: 0,
        };
        this.binding = binding;
        const isRefused = () =>
          maxModelCalls !== undefined && binding.refusedCalls > 0;
        try {
          const result = await operation();
          if (isRefused()) throw new ModelCallRefused();
          return result;
        } catch (error) {
          if (isRefused()) throw new ModelCallRefused();
          throw error;
        } finally {
          this.binding = undefined;
        }
      });
    this.tail = run;
    if (!signal && queueTimeoutMs === undefined) return run;
    return new Promise<T>((resolve, reject) => {
      const abort = (): void =>
        reject(new Error('Profile memory request was cancelled or timed out'));
      const queueTimer =
        queueTimeoutMs === undefined
          ? undefined
          : setTimeout(() => {
              if (isStarted) return;
              isAbandoned = true;
              reject(new EngineBusy());
            }, queueTimeoutMs);
      signal?.addEventListener('abort', abort, { once: true });
      run.then(resolve, reject).finally(() => {
        clearTimeout(queueTimer);
        signal?.removeEventListener('abort', abort);
      });
      if (signal?.aborted) abort();
    });
  }

  async close(): Promise<void> {
    if (this.listener) {
      await closeListener(this.listener.server);
      this.listener = undefined;
    }
  }
}
